 set trace 0
 let value:Bytes=Bytes{last:(tick 1 (- 0 1)),middle:(tick 2 17),first:(tick 3 256)}
 assert (== trace 123)
 assert (== (cast_int value.first) 0)
 assert (== value.middle 17)
 assert (== (cast_int value.last) 255)
 let literal:Bytes=Bytes{first:0,middle:0,last:255}
